<?php
namespace App\Http\Controllers;
use App\Models\PaymentWebhook; use App\Models\User; use App\Models\Wallet; use App\Models\LedgerEntry; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class OperationsController extends Controller { public function health(){return response()->json(['status'=>'ok','service'=>'tokenhub','timestamp'=>now()->toIso8601String()]);} public function metrics(){return response()->json(['users'=>User::count(),'models'=>\App\Models\AiModel::where('is_active',true)->count(),'requests'=>\App\Models\UsageEvent::count(),'revenue_cents'=>(int)\App\Models\UsageEvent::sum('cost_cents'),'failed_requests'=>\App\Models\UsageEvent::where('status','failed')->count()]);} public function paymentWebhook(Request $r){$signature=$r->header('X-TokenHub-Signature');$secret=config('services.tokenhub.webhook_secret',env('TOKENHUB_WEBHOOK_SECRET'));$expected=hash_hmac('sha256',$r->getContent(),$secret);abort_unless($signature && hash_equals($expected,$signature),401);$payload=$r->json()->all();$provider=$payload['provider']??'generic';$eventId=$payload['id']??null;abort_unless($eventId,422);$event=PaymentWebhook::firstOrCreate(['provider'=>$provider,'event_id'=>$eventId],['payload'=>$payload,'status'=>'received']);if($event->wasRecentlyCreated){try{DB::transaction(function() use($payload,$event){$email=$payload['customer_email']??null;$amount=(int)($payload['amount_cents']??0);$u=User::where('email',$email)->firstOrFail();$w=Wallet::firstOrCreate(['user_id'=>$u->id]);$w->increment('balance',$amount);LedgerEntry::create(['user_id'=>$u->id,'type'=>'credit','amount'=>$amount,'description'=>'Payment webhook','reference'=>$event->event_id]);$event->update(['status'=>'processed','processed_at'=>now()]);});}catch(\Throwable $e){$event->update(['status'=>'failed','error'=>$e->getMessage()]);return response()->json(['error'=>'processing_failed'],500);}}return response()->json(['received'=>true,'status'=>$event->fresh()->status]);} }
